window.ATLAS_ITEMS=window.ATLAS_ITEMS||{};window.ATLAS_ITEMS[292]={"id":"292","numero":292,"titre":"Diagnostic des cancers","objectifs":[{"id":"292-1","rang":"A","rubrique":"Étiologies","titre":"Connaître le terrain et les points d’appel","contenu":"<p>Un cancer est évoqué soit sur des <span class=\"kw-clinique\">signes généraux</span>, soit sur des <strong>points d'appel d'organe</strong> liés au <span class=\"kw-def\">syndrome de masse</span> <span class=\"kw-etio\">tumoral</span>. La démarche débute par un <strong>interrogatoire</strong> (<span class=\"kw-def\">terrain</span>, <span class=\"kw-etio\">facteurs de risque</span>) et un <strong>examen clinique complet</strong> appareil par appareil.</p>\n      <table >\n        <thead><tr><th>Appareil</th><th>Points d'appel</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Général</strong></td><td><span class=\"kw-clinique\">Asthénie</span> ; <span class=\"kw-clinique\">anorexie</span> ; <span class=\"kw-clinique\">amaigrissement</span> (dénutrition, sarcopénie) ; <span class=\"kw-clinique\">fièvre</span> ; <span class=\"kw-clinique\">sueurs nocturnes</span></td></tr>\n          <tr><td><strong>Vasculaire</strong></td><td><span class=\"kw-clinique\">TVP</span> / <span class=\"kw-clinique\">EP</span> ; signes <span class=\"kw-clinique\">hémorragiques</span> (tumeur ou coagulopathie)</td></tr>\n          <tr><td><strong>Neurologique</strong></td><td>Déficit <span class=\"kw-clinique\">focal</span> ; atteinte des <span class=\"kw-clinique\">paires crâniennes</span> ; <span class=\"kw-alerte\">HTIC</span> ; <span class=\"kw-alerte\">compression médullaire</span> ; <span class=\"kw-clinique\">syndrome de la</span> <span class=\"kw-clinique\">queue de cheval</span> ; <span class=\"kw-clinique\">radiculalgie</span></td></tr>\n          <tr><td><strong>ORL</strong></td><td><span class=\"kw-clinique\">Dysphonie</span> ; <span class=\"kw-clinique\">dysphagie</span> ; <span class=\"kw-clinique\">ulcération muqueuse</span> ; <span class=\"kw-clinique\">saignements</span> ; <span class=\"kw-clinique\">tuméfaction</span></td></tr>\n          <tr><td><strong>Respiratoire</strong></td><td><span class=\"kw-clinique\">Toux</span> ; <span class=\"kw-clinique\">hémoptysie</span> ; <span class=\"kw-clinique\">dyspnée</span> ; <span class=\"kw-clinique\">douleur thoracique</span> ; <span class=\"kw-clinique\">épanchement pleural</span></td></tr>\n          <tr><td><strong>Digestif</strong></td><td><span class=\"kw-clinique\">Douleurs abdominales</span> ; <span class=\"kw-clinique\">trouble du transit</span> (syndrome occlusif) ; <span class=\"kw-clinique\">saignement digestif</span> (<span class=\"kw-clinique\">méléna</span>, rectorragies) ; <span class=\"kw-clinique\">ascite</span> ; <span class=\"kw-clinique\">ictère</span> ; <span class=\"kw-clinique\">nodule ombilical</span> (de Sœur Marie-Joseph)</td></tr>\n          <tr><td><strong>Urologique</strong></td><td><span class=\"kw-clinique\">Hématurie</span> ; signes fonctionnels urinaires ; <span class=\"kw-clinique\">orchidomégalie</span> ; <span class=\"kw-clinique\">pneumaturie</span> (<span class=\"kw-clinique\">fistule</span> vésico-rectale)</td></tr>\n          <tr><td><strong>Ostéo-articulaire</strong></td><td><span class=\"kw-clinique\">Douleurs osseuses</span> (mécaniques ou inflammatoires, réfractaires aux <span class=\"kw-ttt\">antalgiques</span> de palier 3) ; <span class=\"kw-alerte\">fracture sans traumatisme</span> ; <span class=\"kw-clinique\">tuméfaction</span></td></tr>\n          <tr><td><strong>Dermatologique</strong></td><td><span class=\"kw-clinique\">Lésion</span> <span class=\"kw-clinique\">ABCDE</span> (<span class=\"kw-clinique\">mélanome</span>) ; <span class=\"kw-clinique\">ulcération cutanée</span> ; <span class=\"kw-clinique\">nodules de perméation</span> ; <span class=\"kw-clinique\">prurit</span> ; <span class=\"kw-clinique\">flush</span></td></tr>\n          <tr><td><strong>Hématologique</strong></td><td><span class=\"kw-clinique\">Adénopathie</span> (dure, fixée, indolore) ; <span class=\"kw-clinique\">purpura</span> ; syndrome <span class=\"kw-clinique\">anémique</span> ; <span class=\"kw-clinique\">splénomégalie</span></td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\"><strong><span class=\"kw-clinique\">Mélanome</span> — règle <span class=\"kw-clinique\">ABCDE</span> :</strong> <span class=\"kw-clinique\">A</span>symétrie · <span class=\"kw-clinique\">B</span>ords irréguliers · <span class=\"kw-clinique\">C</span>ouleur inhomogène · <span class=\"kw-chiffre\">D</span>iamètre &gt;<span class=\"kw-chiffre\"> 6 mm</span> · <span class=\"kw-clinique\">É</span>volution récente.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 290 — Epidémiologie cancers</em></p>","frequence":0},{"id":"292-2","rang":"A","rubrique":"Définition","titre":"Connaître la définition des syndromes tumoraux","contenu":"<p>Trois grands <span class=\"kw-def\">syndromes</span> traduisent la présence d'un cancer. <span class=\"kw-clinique\">Les</span> distinguer oriente la démarche diagnostique et le bilan.</p>\n      <table >\n        <thead><tr><th>Syndrome</th><th>Définition</th></tr></thead>\n        <tbody>\n          <tr><td><strong><span class=\"kw-def\">Syndrome cachectique et inflammatoire</span></strong></td><td>Ensemble des signes liés à l'<span class=\"kw-clinique\">altération de l'état général</span> et à l'<span class=\"kw-bio\">état inflammatoire</span> induits par le cancer (<span class=\"kw-clinique\">asthénie</span>, <span class=\"kw-clinique\">anorexie</span>, <span class=\"kw-clinique\">amaigrissement</span>, <span class=\"kw-clinique\">fièvre</span>)</td></tr>\n          <tr><td><strong><span class=\"kw-def\">Syndrome tumoral</span></strong></td><td>Ensemble des signes liés à la présence de la <span class=\"kw-def\">masse tumorale</span> et à ses conséquences <strong>loco-régionales</strong> (<span class=\"kw-clinique\">compression</span>, <span class=\"kw-clinique\">envahissement</span>, <span class=\"kw-clinique\">obstruction</span>)</td></tr>\n          <tr><td><strong><span class=\"kw-def\">Syndrome paranéoplasique</span></strong></td><td>Signes liés à une <span class=\"kw-etio\">tumeur fonctionnelle sécrétante</span> ou à une <span class=\"kw-etio\">maladie auto-immune</span> associée au cancer, <strong>à distance</strong> de la tumeur et <strong>sans lien avec <span class=\"kw-clinique\">les</span> <span class=\"kw-alerte\">métastases</span></strong></td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-info\">Le <span class=\"kw-def\">syndrome paranéoplasique</span> peut être <strong>inaugural</strong> et <strong>précéder</strong> la détection du cancer ; il <strong>régresse en règle avec le traitement</strong> de la tumeur.</div>","frequence":0},{"id":"292-3","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître la démarche diagnostique des cancers","contenu":"<p>La démarche est une <strong>séquence ordonnée</strong> : suspicion clinique → imagerie évocatrice → <strong>preuve anatomopathologique obl<span class=\"kw-chiffre\">iga</span>toire</strong> → <span class=\"kw-def\">bilan d'extension</span> et pré-thérapeutique → <span class=\"kw-def\">stadification</span> <span class=\"kw-def\">TNM</span>.</p>\n      <ol>\n        <li><strong>Suspicion</strong> : <span class=\"kw-clinique\">signes d'appel</span> (généraux ou d'organe), <span class=\"kw-clinique\">découverte fortuite</span> ou <span class=\"kw-bio\">dépistage</span>.</li>\n        <li><strong>Imagerie</strong> : met en évidence un <span class=\"kw-def\">syndrome de masse</span> ; oriente mais <strong>n'affirme jamais</strong> le diagnostic.</li>\n        <li><strong>Preuve histologique / cytologique</strong> : indispensable avant tout traitement (sauf <span class=\"kw-alerte\">urgence</span> vitale).</li>\n        <li><strong>Bilan</strong> : extension (curabilité) + pré-thérapeutique (<span class=\"kw-def\">terrain</span>).</li>\n        <li><strong><span class=\"kw-def\">RCP</span></strong> : décision thérapeutique en <span class=\"kw-def\">réunion de concertation pluridisciplinaire</span>.</li>\n      </ol>\n      <p>Trois situations conduisent à l'<span class=\"kw-imagerie\">imagerie</span> selon la présentation :</p>\n      <table >\n        <thead><tr><th>Présentation</th><th>Imagerie</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Syndrome de <span class=\"kw-clinique\">masse</span></strong> (signe d'organe)</td><td>Examen <strong>guidé par la clinique</strong> : <span class=\"kw-imagerie\">mammographie</span> (sein), <span class=\"kw-imagerie\">TDM thoracique</span> (respiratoire), <span class=\"kw-imagerie\">endoscopie digestive</span> / ORL, <span class=\"kw-imagerie\">cystoscopie</span>…</td></tr>\n          <tr><td><strong><span class=\"kw-clinique\">Cachexie</span> / fièvre isolée</strong></td><td>Imagerie <strong>non orientée</strong> : <span class=\"kw-imagerie\">TDM thoraco-abdomino-pelvien (TAP)</span>, <span class=\"kw-imagerie\">TEP-TDM</span> en 2ᵉ intention</td></tr>\n          <tr><td><strong>Syndrome <span class=\"kw-etio\">paranéoplasique</span></strong></td><td>Imagerie large + médecine nucléaire (<span class=\"kw-imagerie\">scintigraphie</span>, <span class=\"kw-imagerie\">TEP-TDM</span>), ciblant en priorité <span class=\"kw-etio\">poumon</span> et <span class=\"kw-etio\">sein</span></td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-danger\"><strong>Règle d'or :</strong> aucun traitement spécifique n'est débuté sans <span class=\"kw-alerte\">preuve anatomopathologique</span> (histologique ou cytologique). L'imagerie ne suffit jamais.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 294 — Traitement des cancers · 295 — Prise en charge d'un malade cancéreux</em></p>","frequence":0},{"id":"292-4","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître les principaux syndromes paranéoplasiques","contenu":"<p><span class=\"kw-clinique\">Les</span> <span class=\"kw-def\">syndromes paranéoplasiques</span> sont des manifestations systémiques <strong>non liées aux métastases</strong>, dues à la production <span class=\"kw-etio\">tumorale</span> d'une <span class=\"kw-etio\">substance pseudo-hormonale</span> ou à un mécanisme <span class=\"kw-etio\">auto-immun</span>. Le <strong>poumon (CPC et CNPC)</strong> est le cancer le plus pourvoyeur.</p>\n      <table >\n        <thead><tr><th>Catégorie</th><th>Syndrome</th><th>Mécanisme</th><th>Cancers associés</th></tr></thead>\n        <tbody>\n          <tr><td rowspan=\"4\"><strong>Endocrino</strong></td><td><span class=\"kw-def\">SIADH</span> (Schwartz-Bartter)</td><td><span class=\"kw-etio\">ADH</span></td><td><strong>Poumon (CPC)</strong>, SNC, prostate</td></tr>\n          <tr><td>Syndrome de <span class=\"kw-def\">Cushing</span></td><td><span class=\"kw-etio\">ACTH ectopique</span></td><td><strong>Poumon (CPC)</strong></td></tr>\n          <tr><td><span class=\"kw-def\">Hypercalcémie</span></td><td><span class=\"kw-etio\">PTH-rp</span></td><td><strong>Poumon (CNPC)</strong>, sein, rein, ovaire, myélome</td></tr>\n          <tr><td>Syndrome <span class=\"kw-def\">carcinoïde</span></td><td><span class=\"kw-etio\">Sérotonine</span> (5-HIAA)</td><td>TNE du grêle</td></tr>\n          <tr><td rowspan=\"3\"><strong>Neuro</strong></td><td><span class=\"kw-def\">Ataxie cérébelleuse</span></td><td><span class=\"kw-bio\">Ac anti-Hu</span>, <span class=\"kw-bio\">anti-Yo</span></td><td><strong>Poumon (CPC)</strong>, sein, ovaire</td></tr>\n          <tr><td>Syndrome de <span class=\"kw-def\">Lambert-Eaton</span></td><td><span class=\"kw-bio\">Ac anti-canaux calciques</span></td><td><strong>Poumon (CPC)</strong></td></tr>\n          <tr><td><span class=\"kw-def\">Encéphalite limbique</span></td><td><span class=\"kw-bio\">Ac anti-NMDA</span>, <span class=\"kw-bio\">anti-Hu</span></td><td><strong>Poumon (CPC)</strong></td></tr>\n          <tr><td rowspan=\"2\"><strong>Hémato</strong></td><td><span class=\"kw-def\">MTEV</span> / <span class=\"kw-clinique\">syndrome de Trousseau</span> / <span class=\"kw-alerte\">CIVD</span></td><td><span class=\"kw-etio\">Hypercoagulabilité</span></td><td>Tout cancer (surtout <strong>pancréas</strong>, estomac, poumon)</td></tr>\n          <tr><td><span class=\"kw-def\">Polyglobulie</span></td><td><span class=\"kw-etio\">EPO</span></td><td>Rein, CHC, hémangioblastome du cervelet</td></tr>\n          <tr><td><strong>Néphro</strong></td><td><span class=\"kw-def\">GEM</span> (glomérulonéphrite extra-membraneuse)</td><td><span class=\"kw-etio\">Auto-immunité</span></td><td>Poumon, estomac, ovaire, thymus, sein, côlon</td></tr>\n          <tr><td rowspan=\"3\"><strong>Immuno</strong></td><td><span class=\"kw-def\">Dermatomyosite</span> / polymyosite</td><td><span class=\"kw-etio\">Auto-immunité</span></td><td><strong>Poumon (CNPC)</strong>, sein, ovaire</td></tr>\n          <tr><td>Ostéoarthropathie de <span class=\"kw-def\">Pierre-Marie</span></td><td><span class=\"kw-etio\">Auto-immunité</span></td><td><strong>Poumon (CNPC)</strong></td></tr>\n          <tr><td>Syndrome de <span class=\"kw-def\">Stauffer</span></td><td><span class=\"kw-etio\">Auto-immunité</span></td><td>Rein (<span class=\"kw-clinique\">carcinome</span> à cellules claires)</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\"><strong>À retenir :</strong> <span class=\"kw-def\">MTEV</span> = syndrome <span class=\"kw-etio\">paranéoplasique</span> <strong>le plus fréquent</strong>, particulièrement dans <span class=\"kw-clinique\">les</span> cancers du <span class=\"kw-etio\">pancréas</span> et de l'<span class=\"kw-etio\">estomac</span>. Les syndromes <span class=\"kw-etio\">sécrétants</span> dominent dans les <span class=\"kw-def\">tumeurs neuro-endocrines</span> (dont le CPC).</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 226 — Thrombose veineuse profonde - EP · 268 — Hypercalcémie</em></p>","frequence":0},{"id":"292-5","rang":"B","rubrique":"Diagnostic positif","titre":"Connaître les principales manifestations cliniques des syndromes paranéoplasiques","contenu":"<p>Reconnaître le <strong>tableau clinique</strong> d'un syndrome <span class=\"kw-etio\">paranéoplasique</span> permet de le rattacher à un cancer sous-jacent — parfois encore occulte.</p>\n      <table >\n        <thead><tr><th>Syndrome</th><th>Manifestations cliniques</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-def\">SIADH</span></td><td><span class=\"kw-bio\">Hyponatrémie</span> : <span class=\"kw-clinique\">nausées</span>, <span class=\"kw-clinique\">confusion</span>, <span class=\"kw-alerte\">convulsions</span> si profonde et rapide</td></tr>\n          <tr><td><span class=\"kw-def\">Hypercalcémie</span> (PTH-<span class=\"kw-imagerie\">rp</span>)</td><td><span class=\"kw-clinique\">Asthénie</span>, <span class=\"kw-clinique\">constipation</span>, <span class=\"kw-clinique\">syndrome polyuro-polydipsique</span>, <span class=\"kw-clinique\">troubles de conscience</span> ; <span class=\"kw-alerte\">trouble du rythme</span></td></tr>\n          <tr><td>Syndrome de <span class=\"kw-def\">Cushing</span></td><td><span class=\"kw-clinique\">HTA</span>, <span class=\"kw-bio\">hypokaliémie</span>, <span class=\"kw-bio\">diabète</span>, amyotrophie ; installation <strong>rapide</strong></td></tr>\n          <tr><td>Syndrome <span class=\"kw-def\">carcinoïde</span></td><td><span class=\"kw-clinique\">Flush</span> cutané, <span class=\"kw-clinique\">diarrhée</span>, <span class=\"kw-clinique\">bronchospasme</span></td></tr>\n          <tr><td><span class=\"kw-def\">Lambert-Eaton</span></td><td><span class=\"kw-clinique\">Faiblesse musculaire proximale</span> qui <strong>s'améliore à l'effort</strong> (≠ myasthénie)</td></tr>\n          <tr><td><span class=\"kw-def\">Dermatomyosite</span></td><td><span class=\"kw-clinique\">Déficit proximal</span>, <span class=\"kw-clinique\">érythœdème</span> en lunettes, papules de Gottron</td></tr>\n          <tr><td><span class=\"kw-def\">MTEV</span> / Trousseau</td><td><span class=\"kw-clinique\">TVP</span> récidivantes / migratrices, parfois <span class=\"kw-clinique\">EP</span> inaugurale</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-info\"><strong>Discriminant clé :</strong> un <span class=\"kw-def\">Lambert-Eaton</span> se renforce à l'effort, alors que la <span class=\"kw-def\">myasthénie</span> (item thymus) se majore à la fatigue — l'inverse.</div>","frequence":1},{"id":"292-6","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître les signes généraux en cancérologie","contenu":"<p><span class=\"kw-clinique\">Les</span> <span class=\"kw-clinique\">signes généraux</span> traduisent le <span class=\"kw-def\">syndrome cachectique et inflammatoire</span>. Ils sont peu spécifiques mais doivent faire évoquer un cancer surtout s'ils sont <strong>récents, progressifs et inexpliqués</strong>.</p>\n      <ul>\n        <li><strong><span class=\"kw-clinique\">Altération de l'état général (AEG)</span></strong> = triade <span class=\"kw-clinique\">asthénie</span> + <span class=\"kw-clinique\">anorexie</span> + <span class=\"kw-clinique\">amaigrissement</span>, pouvant aller jusqu'à la <span class=\"kw-clinique\">dénutrition</span> et la <span class=\"kw-clinique\">sarcopénie</span>.</li>\n        <li><strong><span class=\"kw-clinique\">Amaigrissement</span></strong> : à <strong>quantifier</strong> — poids actuel, <span class=\"kw-chiffre\">% de perte</span> par rapport au poids de base, <strong>délai</strong> d'installation.</li>\n        <li><strong><span class=\"kw-clinique\">Fièvre</span></strong> et <strong><span class=\"kw-clinique\">sueurs nocturnes</span></strong> (<span class=\"kw-def\">signes B</span> des <span class=\"kw-etio\">lymphomes</span>).</li>\n      </ul>\n      <div class=\"callout callout-warn\"><strong>Réflexe :</strong> chiffrer la perte de poids (<span class=\"kw-chiffre\">≥ 5 %</span> en <span class=\"kw-chiffre\">1 mois</span> ou <span class=\"kw-chiffre\">≥ 10 %</span> en <span class=\"kw-chiffre\">6 mois</span> = <span class=\"kw-clinique\">dénutrition</span>) — c'est un <span class=\"kw-def\">facteur pronostique</span> et un critère décisionnel thérapeutique.</div>","frequence":0},{"id":"292-7","rang":"A","rubrique":"Examens complémentaires","titre":"Connaître la biologie et principales altérations biologiques","contenu":"<p>Aucune anomalie <span class=\"kw-ttt\">biologique</span> n'est spécifique d'un cancer, mais certaines <strong>perturbations doivent le faire évoquer</strong>. On <span class=\"kw-clinique\">les</span> classe selon le syndrome en cause.</p>\n      <table >\n        <thead><tr><th>Origine</th><th>Anomalies biologiques</th></tr></thead>\n        <tbody>\n          <tr><td><strong><span class=\"kw-clinique\">Cachexie</span> / inflammation</strong></td><td>Baisse de l'<span class=\"kw-bio\">albumine</span> et de la <span class=\"kw-bio\">préalbumine</span> ; élévation de la <span class=\"kw-bio\">CRP</span> et du <span class=\"kw-bio\">fibrinogène</span></td></tr>\n          <tr><td><strong>Syndrome de <span class=\"kw-clinique\">masse</span></strong></td><td>Perturbation des fonctions d'organe ; élévation des <span class=\"kw-bio\">LDH</span> ; <span class=\"kw-bio\">hypercalcémie</span> (métastases osseuses) ; <span class=\"kw-alerte\">syndrome de lyse</span> spontané</td></tr>\n          <tr><td><strong><span class=\"kw-etio\">Paranéoplasique</span></strong></td><td><span class=\"kw-bio\">Hypercalcémie</span> (PTH-<span class=\"kw-imagerie\">rp</span>) ; <span class=\"kw-bio\">hyponatrémie</span> (SIADH) ; dosages hormonaux anormaux ; auto-anticorps</td></tr>\n        </tbody>\n      </table>\n      <p><strong>Signes d'appel hématologiques (<span class=\"kw-bio\">NFS</span>) :</strong></p>\n      <ul>\n        <li><span class=\"kw-bio\">Anémie microcytaire ferriprive</span> → saignement chronique.</li>\n        <li><span class=\"kw-bio\">Pancytopénie</span> d'origine centrale → <span class=\"kw-etio\">envahissement médullaire</span> (myélémie, blastes).</li>\n        <li><span class=\"kw-bio\">Thrombocytose</span>, <span class=\"kw-bio\">hyperleucocytose</span> → inflammation chronique.</li>\n        <li><span class=\"kw-bio\">Anémie hémolytique</span> mécanique + <span class=\"kw-bio\">thrombopénie</span> → <span class=\"kw-alerte\">microangiopathie thrombotique</span>.</li>\n      </ul>\n      <p><strong>Signes d'appel biochimiques :</strong> <span class=\"kw-bio\">hyponatrémie</span>, <span class=\"kw-bio\">hypercalcémie</span> (<span class=\"kw-bio\">ionogramme</span>) ; élévation de la <span class=\"kw-bio\">créatininémie</span> (obstacle) ; <span class=\"kw-bio\">cholestase</span> / <span class=\"kw-bio\">cytolyse</span> (foie) ; élévation des <span class=\"kw-bio\">LDH</span> (prolifération, lymphome) ; sang dans <span class=\"kw-clinique\">les</span> selles (<span class=\"kw-bio\">test immunologique</span> CCR).</p>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 268 — Hypercalcémie</em></p>","frequence":0},{"id":"292-8","rang":"A","rubrique":"Définition","titre":"Connaître les principes d’utilisation des marqueurs tumoraux","contenu":"<p>Un <span class=\"kw-def\">marqueur tumoral</span> est une substance (sang, urines, tissu) pouvant indiquer la présence d'un cancer. Sa principale indication est la <strong><span class=\"kw-def\">surveillance</span></strong>, pas le diagnostic.</p>\n      <table >\n        <thead><tr><th>Phase</th><th>Place des marqueurs</th></tr></thead>\n        <tbody>\n          <tr><td><strong><span class=\"kw-def\">Dépistage</span></strong></td><td><strong>Très limité</strong> : seuls le <span class=\"kw-bio\">PSA</span> (prostate) et l'<span class=\"kw-bio\">αFP</span> (CHC chez le cirrhotique) sont utilisés en <span class=\"kw-def\">dépistage</span> ciblé</td></tr>\n          <tr><td><strong>Diagnostic</strong></td><td><strong>Quasi aucun</strong>, sauf tumeurs <span class=\"kw-etio\">germinales</span> (<span class=\"kw-bio\">hCG</span>, <span class=\"kw-bio\">αFP</span>, <span class=\"kw-bio\">LDH</span>)</td></tr>\n          <tr><td><strong><span class=\"kw-def\">Pronostic</span></strong></td><td><span class=\"kw-bio\">CA 19-9</span> (pancréas), <span class=\"kw-bio\">ACE</span> (côlon-rectum), <span class=\"kw-bio\">αFP</span> (CHC)</td></tr>\n          <tr><td><strong><span class=\"kw-def\">Surveillance</span></strong> ⭐</td><td><strong>Indication principale</strong> : <span class=\"kw-bio\">PSA</span> (prostate), <span class=\"kw-bio\">thyroglobuline</span> (thyroïde), <span class=\"kw-bio\">CA 125</span> (ovaire), <span class=\"kw-bio\">ACE</span> (côlon)</td></tr>\n        </tbody>\n      </table>\n      <p><strong>Principaux marqueurs par localisation :</strong></p>\n      <ul>\n        <li><span class=\"kw-bio\">PSA</span> → prostate · <span class=\"kw-bio\">αFP</span> → CHC · <span class=\"kw-bio\">CA 19-9</span> → pancréas</li>\n        <li><span class=\"kw-bio\">CA 125</span> → ovaire · <span class=\"kw-bio\">ACE</span> → côlon-rectum · <span class=\"kw-bio\">thyroglobuline</span> → thyroïde différenciée · <span class=\"kw-bio\">SCC</span> → épidermoïdes</li>\n      </ul>\n      <div class=\"callout callout-danger\"><strong>Piège classique :</strong> un marqueur <span class=\"kw-etio\">tumoral</span> peut être <span class=\"kw-alerte\">élevé dans des affections non cancéreuses</span> et <strong>normal en présence d'un cancer</strong>. Il ne fait <strong>jamais</strong> le diagnostic — toujours interprété avec l'imagerie et l'<span class=\"kw-bio\">histologie</span>.</div>","frequence":1},{"id":"292-9","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître la place de l’examen anatomo-pathologique en cancérologie","contenu":"<div class=\"obj-callout success\"><strong>Principe fondamental :</strong> le diagnostic de cancer est <strong>posé par l'examen <span class=\"kw-bio\">histologique</span> ou <span class=\"kw-bio\">cytologique</span></strong> d'un échantillon de tissu <span class=\"kw-etio\">tumoral</span> (tumeur primitive ou métastase). Pas de cancer sans preuve anatomopathologique.</div>\n      <p>L'examen anatomopathologique remplit <strong>trois objectifs</strong> :</p>\n      <table >\n        <thead><tr><th>Objectif</th><th>Apport</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Diagnostic</strong></td><td>Affirme la <span class=\"kw-def\">malignité</span> ; précise le <span class=\"kw-def\">type histologique</span> et l'organe d'origine (<span class=\"kw-bio\">immunohistochimie</span> si besoin)</td></tr>\n          <tr><td><strong><span class=\"kw-def\">Pronostic</span></strong></td><td><span class=\"kw-bio\">Activité mitotique</span> ; degré d'<span class=\"kw-bio\">invasion</span> (emboles, engainements) ; degré de <span class=\"kw-bio\">différenciation</span> ; grades (Gleason, Ki67, Elston-Ellis)</td></tr>\n          <tr><td><strong>Thérapeutique</strong></td><td>Recherche d'<span class=\"kw-etio\">anomalies moléculaires</span> pour <span class=\"kw-clinique\">les</span> <span class=\"kw-ttt\">thérapies ciblées</span> (EGFR poumon, RH/HER2 sein, RAS côlon)</td></tr>\n        </tbody>\n      </table>\n      <p><strong>Choix du prélèvement</strong> (balance bénéfice/risque) :</p>\n      <ul>\n        <li>Privilégier <span class=\"kw-clinique\">les</span> <strong>sites accessibles</strong> : <span class=\"kw-clinique\">lésion</span> <span class=\"kw-clinique\">mammaire</span>, <span class=\"kw-clinique\">hépatique</span> ou <span class=\"kw-clinique\">ganglionnaire sus-claviculaire</span> plutôt que pancréatique / rétropéritonéale.</li>\n        <li>Privilégier la <strong><span class=\"kw-ttt\">biopsie</span></strong> à la <strong>cytoponction</strong> (plus de tissu, analyses moléculaires possibles).</li>\n        <li><span class=\"kw-alerte\">Biopsie osseuse</span> : rentabilité modérée (décalcification, analyses moléculaires difficiles).</li>\n      </ul>\n      <table >\n        <thead><tr><th>Technique</th><th>Caractéristiques</th></tr></thead>\n        <tbody>\n          <tr><td><strong><span class=\"kw-bio\">Cytologie</span></strong></td><td>Cellules isolées (frottis, <span class=\"kw-ttt\">ponction</span> à l'aiguille fine, liquide) ; <span class=\"kw-alerte\">n'a de valeur que si positive (mauvaise VPN)</span> ; ne précise <strong>ni</strong> type histologique <strong>ni</strong> <span class=\"kw-bio\">différenciation</span></td></tr>\n          <tr><td><strong><span class=\"kw-bio\">Histologie</span></strong></td><td><span class=\"kw-ttt\">Biopsie</span> / pièce opératoire ; étudie anomalies cytologiques <strong>et</strong> architecturales (type, invasion, <span class=\"kw-bio\">différenciation</span>) ; <strong>VPN supérieure</strong> à la cytologie</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\"><strong>À retenir :</strong> <span class=\"kw-bio\">immunohistochimie</span> <strong>obl<span class=\"kw-chiffre\">iga</span>toire</strong> pour : mésothéliome, TNE du pancréas, lymphome, GIST, CPC. <strong>Double lecture INCa</strong> systématique pour : <span class=\"kw-def\">sarcomes</span>, <span class=\"kw-def\">lymphomes</span>, <span class=\"kw-def\">mésothéliomes</span>, <span class=\"kw-def\">TNE rares</span>.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 291 — Cancérogénèse - oncogénétique · 293 — Anapath</em></p>","frequence":3},{"id":"292-10","rang":"B","rubrique":"Définition","titre":"Connaître le vocabulaire minimum nécessaire à la compréhension d’un compte-rendu anatomopathologique de tumeur","contenu":"<p>La nomenclature des tumeurs repose sur le <strong>tissu reproduit</strong> (phénotype) et le caractère <strong>bénin ou malin</strong>.</p>\n      <table >\n        <thead><tr><th>Terme</th><th>Définition</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-def\">Adénome</span></td><td>Tumeur épithéliale <strong>glandulaire bénigne</strong></td></tr>\n          <tr><td><span class=\"kw-def\">Carcinome</span></td><td>Tumeur <strong>épithéliale maligne</strong> (ex. adénocarcinome = glandulaire)</td></tr>\n          <tr><td><span class=\"kw-def\">Carcinome in situ</span></td><td>Cellules cancéreuses <strong>ne franchissant pas la <span class=\"kw-bio\">membrane basale</span></strong> = <span class=\"kw-def\">stade 0</span>, non invasif (≈ « <span class=\"kw-def\">dysplasie de haut grade</span> »)</td></tr>\n          <tr><td><span class=\"kw-def\">Carcinome invasif</span></td><td><span class=\"kw-clinique\">Carcinome</span> ayant <strong>franchi la <span class=\"kw-bio\">membrane basale</span></strong> et envahi le <span class=\"kw-bio\">tissu conjonctif</span></td></tr>\n          <tr><td><span class=\"kw-def\">Sarcome</span></td><td>Tumeur <strong>conjonctive maligne</strong> (ostéo-, chondro-, léiomyo-…)</td></tr>\n          <tr><td><span class=\"kw-def\">Mélanome</span></td><td>Tumeur maligne des <span class=\"kw-bio\">mélanocytes</span></td></tr>\n          <tr><td><span class=\"kw-def\">Papillome</span></td><td>Tumeur épithéliale <strong>bénigne</strong> d'un épithélium de revêtement</td></tr>\n        </tbody>\n      </table>\n      <p><strong>Données minimales du compte-rendu</strong> sur pièce opératoire :</p>\n      <table >\n        <thead><tr><th>Rubrique</th><th>Contenu</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Type</strong></td><td>Type histologique (<span class=\"kw-def\">classification</span> <span class=\"kw-def\">OMS</span>)</td></tr>\n          <tr><td><strong><span class=\"kw-def\">Pronostic</span></strong></td><td>Facteurs histopronostiques (Gleason, Elston-Ellis, Ki67, contingent non séminomateux)</td></tr>\n          <tr><td><strong>TNM</strong></td><td><span class=\"kw-def\">pTNM</span> (histologique) / <span class=\"kw-def\">ypTNM</span> (après néo-adjuvant)</td></tr>\n          <tr><td><strong>Marges (R)</strong></td><td><strong>R0</strong> marges saines · <strong>R1</strong> atteinte microscopique · <strong>R2</strong> résidu macroscopique</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-info\">La <strong>marge de résection</strong> = distance minimale (mm) entre la tumeur et la tranche de section. La <span class=\"kw-def\">qualité d'exérèse R</span> conditionne le risque de récidive locale.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 293 — Anapath</em></p>","frequence":2},{"id":"292-11","rang":"A","rubrique":"Examens complémentaires","titre":"Savoir distinguer bilan d’extension et bilan pré-thérapeutique","contenu":"<p>Une fois la <span class=\"kw-def\">malignité</span> prouvée, deux bilans <strong>distincts et complémentaires</strong> sont prescrits — à ne pas confondre : le bilan d'<span class=\"kw-def\">extension</span> et le bilan <span class=\"kw-def\">pré-thérapeutique</span>.</p>\n      <table >\n        <thead><tr><th></th><th><span class=\"kw-def\">Bilan d'extension</span></th><th><span class=\"kw-ci\">Bilan pré-thérapeutique</span></th></tr></thead>\n        <tbody>\n          <tr><td><strong>Objectif</strong></td><td>Évaluer l'<span class=\"kw-def\">extension</span> de la maladie</td><td>Évaluer le <span class=\"kw-def\">terrain</span> et <span class=\"kw-clinique\">les</span> <span class=\"kw-clinique\">comorbidités</span></td></tr>\n          <tr><td><strong>Question</strong></td><td><span class=\"kw-def\">Curabilité</span> <span class=\"kw-bio\">vs</span> <span class=\"kw-alerte\">incurabilité</span> (<span class=\"kw-def\">palliatif</span>)</td><td>Quels traitements le patient peut-il <strong>recevoir / supporter</strong> ?</td></tr>\n          <tr><td><strong>Moyens</strong></td><td><span class=\"kw-imagerie\">Imagerie loco-régionale</span> ± à distance ; <span class=\"kw-def\">stadification</span> <span class=\"kw-def\">TNM</span></td><td>État général (<span class=\"kw-def\">PS</span>, <span class=\"kw-def\">G8</span>), <span class=\"kw-bio\">biologie d'organe</span>, <span class=\"kw-clinique\">consultation d'anesthésie</span></td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-info\"><strong>En une phrase :</strong> le bilan d'<strong>extension</strong> répond à « <em>jusqu'où va le cancer ?</em> », le bilan <strong>pré-thérapeutique</strong> à « <em>que peut supporter le patient ?</em> ».</div>","frequence":0},{"id":"292-12","rang":"B","rubrique":"Examens complémentaires","titre":"Connaître le rationnel d’un bilan d’extension","contenu":"<p>Le <span class=\"kw-def\">bilan d'extension</span> est <strong>adapté au primitif, au type histologique et au <span class=\"kw-def\">pronostic</span></strong> initial. Son ampleur croît avec le risque métastatique.</p>\n      <table >\n        <thead><tr><th>Pronostic</th><th>Bilan</th><th>Exemples</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Bon</strong></td><td><span class=\"kw-imagerie\">Imagerie loco-régionale</span> seule</td><td>Prostate faible risque, sein T1-T2 N0, thyroïde N−</td></tr>\n          <tr><td><strong>Intermédiaire</strong></td><td>Extension élargie : <span class=\"kw-imagerie\">TEP-TDM</span>, <span class=\"kw-imagerie\">IRM</span>, <span class=\"kw-imagerie\">scintigraphie osseuse</span> selon recos</td><td>Sein T3-T4 / N+, rein, VADS, endomètre FIGO 1-2</td></tr>\n          <tr><td><strong>Mauvais</strong></td><td>Loco-régional <strong>+ à distance</strong> : <span class=\"kw-imagerie\">TDM-TAP</span> ± <span class=\"kw-imagerie\">IRM cérébrale</span> ± <span class=\"kw-imagerie\">TEP-TDM</span></td><td>Sein <span class=\"kw-etio\">inflammatoire</span>, poumon, pancréas, cancers digestifs</td></tr>\n        </tbody>\n      </table>\n      <ul>\n        <li><strong><span class=\"kw-def\">Stade</span> localisé</strong> : au minimum un bilan <span class=\"kw-imagerie\">loco-régional</span> (taille, <span class=\"kw-clinique\">envahissement local</span>, <span class=\"kw-clinique\">ganglions</span>) → complété à distance selon le risque de <span class=\"kw-alerte\">métastases synchrones</span> et le <span class=\"kw-def\">terrain</span>.</li>\n        <li><strong>Maladie <span class=\"kw-alerte\">métastatique</span></strong> : <span class=\"kw-imagerie\">TDM-TAP</span> = examen de référence ; sert d'<strong>imagerie de référence initiale</strong> et au choix des cibles de <span class=\"kw-def\">suivi</span>.</li>\n      </ul>\n      <div class=\"callout callout-warn\"><strong>Exemple-piège (VADS) :</strong> dans <span class=\"kw-clinique\">les</span> carcinomes épidermoïdes des VADS, risque de <strong>cancer synchrone</strong> (poumon, 2ᵉ VADS) de <span class=\"kw-chiffre\">10-15 %</span> → bilan complété par <span class=\"kw-imagerie\">TDM thoracique</span> en coupes fines + <strong>pan-endoscopie</strong>.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 294 — Traitement des cancers</em></p>","frequence":0},{"id":"292-13","rang":"B","rubrique":"Définition","titre":"Connaître le bilan préthérapeutique clinique","contenu":"<p>Le <span class=\"kw-ci\">bilan pré-thérapeutique</span> <strong>clinique</strong> évalue si le patient peut recevoir <span class=\"kw-clinique\">les</span> traitements recommandés. Il repose sur l'évaluation de l'<span class=\"kw-def\">état général</span>.</p>\n      <p><strong><span class=\"kw-def\">Performance Status (PS) OMS</span></strong> — outil clé de décision :</p>\n      <table >\n        <thead><tr><th>PS</th><th>État</th><th>Conséquence thérapeutique</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-chiffre\">0</span></td><td>Activité normale</td><td rowspan=\"2\">Traitements <strong>intensifs</strong> possibles (<span class=\"kw-ttt\">chirurgie</span>, chimio-<span class=\"kw-imagerie\">RT</span>)</td></tr>\n          <tr><td><span class=\"kw-chiffre\">1</span></td><td>Activité réduite, ambulatoire</td></tr>\n          <tr><td><span class=\"kw-chiffre\">2</span></td><td>Alité &lt;<span class=\"kw-chiffre\"> 50 %</span> du temps, autonome</td><td>Évaluation <strong>au cas par cas</strong>, traitements atténués</td></tr>\n          <tr><td><span class=\"kw-chiffre\">3</span></td><td>Alité &gt;<span class=\"kw-chiffre\"> 50 %</span> du temps</td><td rowspan=\"2\"><span class=\"kw-alerte\">Soins palliatifs privilégiés</span> ; exclusion des essais</td></tr>\n          <tr><td><span class=\"kw-chiffre\">4</span></td><td>Alité en permanence, dépendant</td></tr>\n        </tbody>\n      </table>\n      <ul>\n        <li><strong>Oncogériatrie</strong> : après <span class=\"kw-chiffre\">75 ans</span>, <span class=\"kw-def\">dépistage</span> par le <span class=\"kw-def\">score G8</span> ; <span class=\"kw-chiffre\">G8 ≤ 14</span> → évaluation gériatrique spécialisée.</li>\n        <li><strong><span class=\"kw-clinique\">Consultation d'anesthésie</span></strong> : <strong>obl<span class=\"kw-chiffre\">iga</span>toire</strong> avant toute <span class=\"kw-ttt\">chirurgie</span> (risque anesthésique et post-opératoire).</li>\n        <li>Tout dossier est discuté en <span class=\"kw-def\">RCP</span>.</li>\n      </ul>\n      <div class=\"callout callout-danger\"><strong>Seuil décisionnel :</strong> <span class=\"kw-ttt\">chirurgie</span>, chimio-<span class=\"kw-ttt\">radiothérapie</span> et chimiothérapie ne sont en règle possibles que pour un <span class=\"kw-chiffre\">PS 0-2</span>. Un <span class=\"kw-alerte\">PS ≥ 3</span> en situation incurable fait habituellement arrêter <span class=\"kw-clinique\">les</span> traitements spécifiques (risque de toxicité).</div>","frequence":0},{"id":"292-14","rang":"A","rubrique":"Suivi et/ou pronostic","titre":"Connaître les principes de stadification TNM","contenu":"<p>La <span class=\"kw-def\">classification</span> <span class=\"kw-def\">TNM</span> décrit l'extension anatomique de la tumeur ; elle est <strong>propre à chaque cancer</strong> et fonde la <strong><span class=\"kw-def\">stadification</span></strong>, qui guide le traitement et le <span class=\"kw-def\">pronostic</span>.</p>\n      <table >\n        <thead><tr><th>Lettre</th><th>Signification</th></tr></thead>\n        <tbody>\n          <tr><td><strong><span class=\"kw-def\">T</span></strong> (Tumor)</td><td>Taille de la tumeur primitive et/ou <span class=\"kw-bio\">envahissement</span> local, de <span class=\"kw-chiffre\">T1</span> à <span class=\"kw-chiffre\">T4</span></td></tr>\n          <tr><td><strong><span class=\"kw-def\">N</span></strong> (Node)</td><td><span class=\"kw-bio\">Envahissement</span> <span class=\"kw-clinique\">ganglionnaire</span> du territoire de <span class=\"kw-ttt\">drainage</span></td></tr>\n          <tr><td><strong><span class=\"kw-def\">M</span></strong> (Metastasis)</td><td>Présence (<span class=\"kw-chiffre\">M1</span>) ou absence (<span class=\"kw-chiffre\">M0</span>) de <span class=\"kw-alerte\">métastases à distance</span></td></tr>\n          <tr><td><strong>x</strong></td><td>Item non évaluable (<span class=\"kw-chiffre\">Tx</span>, <span class=\"kw-chiffre\">Nx</span>, <span class=\"kw-chiffre\">Mx</span>)</td></tr>\n        </tbody>\n      </table>\n      <p><strong>Préfixes selon la méthode d'évaluation :</strong></p>\n      <table >\n        <thead><tr><th>Préfixe</th><th>Méthode</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-def\">cTNM</span></td><td><strong>Clinique</strong> — après bilan initial (clinique + paraclinique), <strong>avant</strong> traitement</td></tr>\n          <tr><td><span class=\"kw-def\">pTNM</span></td><td><strong>Histologique</strong> (« pathological ») — sur pièce opératoire</td></tr>\n          <tr><td><span class=\"kw-def\">usTNM</span></td><td><strong>Échographique</strong></td></tr>\n          <tr><td><span class=\"kw-def\">yTNM</span> ⭐</td><td>Après <strong>traitement néo-adjuvant</strong></td></tr>\n          <tr><td><span class=\"kw-def\">ypTNM</span> ⭐</td><td><strong>Histologique après néo-adjuvant</strong></td></tr>\n        </tbody>\n      </table>\n      <p><strong><span class=\"kw-def\">Stadification</span></strong> — regroupement des TNM homogènes en <span class=\"kw-def\">pronostic</span>/traitement (critère principal = <span class=\"kw-def\">survie</span>) :</p>\n      <table >\n        <thead><tr><th><span class=\"kw-def\">Stade</span></th><th>Définition</th></tr></thead>\n        <tbody>\n          <tr><td><strong><span class=\"kw-def\">Stade</span> 0</strong></td><td>Cancer <span class=\"kw-def\">in situ</span></td></tr>\n          <tr><td><strong><span class=\"kw-def\">Stade</span> 1</strong></td><td>Tumeur unique de petite taille, <strong>pas</strong> d'atteinte ganglionnaire ni de métastase</td></tr>\n          <tr><td><strong><span class=\"kw-def\">Stade</span> 2</strong></td><td>Limité à l'organe d'origine, quasiment jamais d'atteinte ganglionnaire</td></tr>\n          <tr><td><strong><span class=\"kw-def\">Stade</span> 3</strong></td><td>Extension <span class=\"kw-clinique\">loco-régionale</span> (organes de voisinage et/ou <span class=\"kw-clinique\">atteinte ganglionnaire</span>)</td></tr>\n          <tr><td><strong><span class=\"kw-def\">Stade</span> 4</strong></td><td>Atteinte <span class=\"kw-alerte\">métastatique</span> à distance</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\"><strong>À retenir :</strong> à chaque <strong><span class=\"kw-def\">stade</span></strong> correspond un traitement qui offre la meilleure <span class=\"kw-def\">survie</span>. Le <span class=\"kw-def\">pTNM</span> est plus précis que le <span class=\"kw-def\">cTNM</span> mais ne peut en règle préciser le <span class=\"kw-chiffre\">M</span> (pièce opératoire localisée).</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 294 — Traitement des cancers</em></p>","frequence":3},{"id":"292-15","rang":"A","rubrique":"Suivi et/ou pronostic","titre":"Connaître les caractéristiques pronostiques cliniques","contenu":"<p>Au-delà du <span class=\"kw-def\">stade TNM</span>, des <span class=\"kw-def\">facteurs cliniques</span> modulent le <span class=\"kw-def\">pronostic</span> et la décision thérapeutique.</p>\n      <table >\n        <thead><tr><th>Catégorie</th><th>Facteurs pronostiques</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Propres au patient</strong></td><td><span class=\"kw-def\">Performance status</span> ; <span class=\"kw-clinique\">dénutrition</span> ; <span class=\"kw-clinique\">comorbidités</span> (notamment <span class=\"kw-clinique\">dysfonctions d'organe</span>)</td></tr>\n          <tr><td><strong>Liés au retentissement du cancer</strong></td><td><span class=\"kw-clinique\">Métastases osseuses</span> avec <span class=\"kw-alerte\">complications neurologiques</span> ; métastases à risque de <span class=\"kw-alerte\">saignement</span> ; <span class=\"kw-clinique\">dysfonction d'organe</span> par <span class=\"kw-clinique\">envahissement tumoral</span></td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-info\">Le <span class=\"kw-def\">PS</span> et la <span class=\"kw-clinique\">dénutrition</span> sont <span class=\"kw-clinique\">les</span> deux <span class=\"kw-def\">facteurs pronostiques cliniques</span> les plus discriminants — ils conditionnent directement la <strong>faisabilité des traitements</strong> (cf. <span class=\"kw-ci\">bilan pré-thérapeutique</span>).</div>","frequence":0},{"id":"292-16","rang":"B","rubrique":"Suivi et/ou pronostic","titre":"Connaître les principaux facteurs pronostiques anatomopathologiques","contenu":"<p>L'examen <span class=\"kw-bio\">anatomopathologique</span> fournit des <span class=\"kw-def\">facteurs histopronostiques</span> = aspects histologiques démontrés comme influençant significativement le <span class=\"kw-def\">pronostic</span>.</p>\n      <table >\n        <thead><tr><th>Facteur</th><th>Description</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-bio\">Activité mitotique</span></td><td>Index de prolifération (nombre de <span class=\"kw-bio\">mitoses</span>)</td></tr>\n          <tr><td><span class=\"kw-bio\">Degré d'invasion</span></td><td>Franchissement des couches tissulaires ; <span class=\"kw-alerte\">emboles vasculaires</span> ; <span class=\"kw-alerte\">engainements périnerveux</span></td></tr>\n          <tr><td><span class=\"kw-bio\">Degré de différenciation</span></td><td>Perte des caractéristiques morphologiques du tissu d'origine (cytologique et histologique)</td></tr>\n          <tr><td><span class=\"kw-etio\">Facteurs moléculaires</span></td><td>Ex. <span class=\"kw-bio\">BRAF</span> muté = mauvais <span class=\"kw-def\">pronostic</span> dans le CCR métastatique</td></tr>\n        </tbody>\n      </table>\n      <p><strong>Grades histopronostiques validés</strong> (propres à chaque tumeur) :</p>\n      <ul>\n        <li><span class=\"kw-def\">Score</span> de <span class=\"kw-def\">Gleason / ISUP</span> → cancer de la <span class=\"kw-etio\">prostate</span>.</li>\n        <li>Index de prolifération <span class=\"kw-def\">Ki67</span> → <span class=\"kw-etio\">tumeurs neuro-endocrines</span>.</li>\n        <li><span class=\"kw-def\">Classification</span> d'<span class=\"kw-def\">Elston-Ellis (SBR modifié)</span> → cancer du <span class=\"kw-etio\">sein</span>.</li>\n      </ul>\n      <div class=\"callout callout-warn\"><strong>Réflexe QCM :</strong> associer chaque <span class=\"kw-def\">grade</span> à son organe — Gleason ⇄ prostate, Ki67 ⇄ TNE, Elston-Ellis/SBR ⇄ sein.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 293 — Anapath</em></p>","frequence":0}],"astuces":[],"strategie":{"principes":"<p><em>Stratégie de prise en charge à compléter — non disponible dans la source GitHub pour cet item.</em></p>"},"cards":[{"i":"2bf14879eb14","n":292,"o":"292-1","u":"Étiologies","t":"Connaître le terrain et les points d’appel","q":"Quels sont les signes généraux évocateurs d'un cancer à rechercher à l'interrogatoire et à l'examen clinique ?","a":"<p>Les signes généraux évocateurs d'un cancer sont :</p><ul><li><strong>Asthénie</strong></li><li><strong>Anorexie</strong></li><li><strong>Amaigrissement</strong> (dénutrition, sarcopénie)</li><li><strong>Fièvre</strong></li><li><strong>Sueurs nocturnes</strong></li></ul>"},{"i":"66ec692342d3","n":292,"o":"292-1","u":"Étiologies","t":"Connaître le terrain et les points d’appel","q":"Décrivez la règle ABCDE pour l'examen d'une lésion cutanée évocatrice de mélanome.","a":"<p>La règle <strong>ABCDE</strong> pour le mélanome signifie :</p><ul><li><strong>A</strong>symétrie</li><li><strong>B</strong>ords irréguliers</li><li><strong>C</strong>ouleur inhomogène</li><li><strong>D</strong>iamètre > <strong>6 mm</strong></li><li><strong>É</strong>volution récente</li></ul>"},{"i":"a299c1042165","n":292,"o":"292-1","u":"Étiologies","t":"Connaître le terrain et les points d’appel","q":"Quels sont les points d'appel digestifs qui peuvent faire évoquer un cancer ?","a":"<p>Les points d'appel digestifs sont :</p><ul><li><strong>Douleurs abdominales</strong></li><li><strong>Trouble du transit</strong> (syndrome occlusif)</li><li><strong>Saignement digestif</strong> (méléna, rectorragies)</li><li><strong>Ascite</strong></li><li><strong>Ictère</strong></li><li><strong>Nodule ombilical</strong> (de Sœur Marie-Joseph)</li></ul>"},{"i":"fdd5eea726ed","n":292,"o":"292-1","u":"Étiologies","t":"Connaître le terrain et les points d’appel","q":"Quels sont les points d'appel hématologiques et dermatologiques qui peuvent faire évoquer un cancer ?","a":"<p>Les points d'appel hématologiques sont :</p><ul><li><strong>Adénopathie</strong> (dure, fixée, indolore)</li><li><strong>Purpura</strong></li><li><strong>Syndrome anémique</strong></li><li><strong>Splénomégalie</strong></li></ul><p>Les points d'appel dermatologiques sont :</p><ul><li><strong>Lésion ABCDE</strong> (mélanome)</li><li><strong>Ulcération cutanée</strong></li><li><strong>Nodules de perméation</strong></li><li><strong>Prurit</strong></li><li><strong>Flush</strong></li></ul>"},{"i":"3e65b665e04f","n":292,"o":"292-11","u":"Examens complémentaires","t":"Savoir distinguer bilan d’extension et bilan pré-thérapeutique","q":"Quel est l'objectif du bilan d'extension dans le diagnostic des cancers ?","a":"<p>L'objectif du <strong>bilan d'extension</strong> est d'évaluer <strong>l'extension de la maladie cancéreuse</strong>. Il vise à déterminer si le cancer est curable ou s'il relève de soins palliatifs.</p>"},{"i":"9a7a8752efc1","n":292,"o":"292-11","u":"Examens complémentaires","t":"Savoir distinguer bilan d’extension et bilan pré-thérapeutique","q":"Quels sont les moyens utilisés pour réaliser un bilan d'extension des cancers ?","a":"<p>Les moyens utilisés pour le bilan d'extension sont l'<strong>imagerie loco-régionale</strong> et potentiellement l'imagerie à distance. Cela permet d'établir la <strong>stadification TNM</strong> du cancer.</p>"},{"i":"c0bd9c596ecd","n":292,"o":"292-11","u":"Examens complémentaires","t":"Savoir distinguer bilan d’extension et bilan pré-thérapeutique","q":"Quel est l'objectif du bilan pré-thérapeutique dans le diagnostic des cancers et quels en sont les moyens ?","a":"<p>L'objectif du <strong>bilan pré-thérapeutique</strong> est d'<strong>évaluer le terrain et les comorbidités</strong> du patient afin de déterminer quels traitements il peut supporter. Les moyens incluent l'évaluation de l'<strong>état général</strong> (score de performance tel que le <strong>PS</strong> ou le <strong>G8</strong>), la <strong>biologie d'organe</strong> et une <strong>consultation d'anesthésie</strong>.</p>"},{"i":"1d4cce6d509a","n":292,"o":"292-14","u":"Suivi et/ou pronostic","t":"Connaître les principes de stadification TNM","q":"Quel est l'intérêt d'une stadification des cancers par regroupement des TNM ?","a":"<p>La stadification regroupe les TNM homogènes en termes de <strong>pronostic et de traitement</strong>. Le critère principal de regroupement est la <strong>survie</strong>. À chaque stade correspond un traitement qui offre la meilleure survie.</p>"},{"i":"310426be5303","n":292,"o":"292-14","u":"Suivi et/ou pronostic","t":"Connaître les principes de stadification TNM","q":"Que signifient les lettres T, N et M dans la classification TNM des cancers ?","a":"<ul><li><strong>T (Tumor)</strong> : Décrit la <strong>taille de la tumeur primitive</strong> et/ou son envahissement local, classé de T1 à T4.</li><li><strong>N (Node)</strong> : Indique l'<strong>envahissement ganglionnaire</strong> dans le territoire de drainage (N0, N1, N2...).</li><li><strong>M (Metastasis)</strong> : Précise la présence (<strong>M1</strong>) ou l'absence (<strong>M0</strong>) de métastases à distance.</li></ul>"},{"i":"8607a24a0ed0","n":292,"o":"292-14","u":"Suivi et/ou pronostic","t":"Connaître les principes de stadification TNM","q":"Quel est l'intérêt du pTNM par rapport au cTNM dans le diagnostic des cancers ?","a":"<p>Le <strong>pTNM</strong> (histologique sur pièce opératoire) est généralement <strong>plus précis</strong> que le cTNM (clinique). Cependant, il ne peut en règle générale pas préciser l'existence de métastases à distance (le M), car la pièce opératoire est localisée.</p>"},{"i":"b22a732128d9","n":292,"o":"292-14","u":"Suivi et/ou pronostic","t":"Connaître les principes de stadification TNM","q":"Quels sont les différents préfixes utilisés avec la classification TNM et leur signification pour le diagnostic des cancers ?","a":"<ul><li><strong>cTNM (clinique)</strong> : Évaluation après le bilan initial (clinique et paraclinique), avant tout traitement.</li><li><strong>pTNM (pathological)</strong> : Évaluation histologique réalisée sur la <strong>pièce opératoire</strong>.</li><li><strong>yTNM</strong> : Évaluation effectuée <strong>après un traitement néo-adjuvant</strong>.</li><li><strong>ypTNM</strong> : Évaluation histologique réalisée <strong>après un traitement néo-adjuvant</strong> (sur pièce opératoire).</li></ul>"},{"i":"cdad85098f09","n":292,"o":"292-14","u":"Suivi et/ou pronostic","t":"Connaître les principes de stadification TNM","q":"Comment les stades 0 à 4 sont-ils définis dans la stadification des cancers ?","a":"<ul><li><strong>Stade 0</strong> : Cancer <strong>in situ</strong>.</li><li><strong>Stade 1</strong> : Tumeur unique de <strong>petite taille</strong>, sans atteinte ganglionnaire ni métastase.</li><li><strong>Stade 2</strong> : Tumeur limitée à l'<strong>organe d'origine</strong>, quasiment sans atteinte ganglionnaire.</li><li><strong>Stade 3</strong> : <strong>Extension loco-régionale</strong> (organes de voisinage et/ou atteinte ganglionnaire).</li><li><strong>Stade 4</strong> : Atteinte <strong>métastatique à distance</strong>.</li></ul>"},{"i":"fb7bda56dc34","n":292,"o":"292-14","u":"Suivi et/ou pronostic","t":"Connaître les principes de stadification TNM","q":"Quelle est la fonction principale de la classification TNM dans le diagnostic des cancers ?","a":"<p>La classification TNM décrit l'<strong>extension anatomique de la tumeur</strong>. Elle est spécifique à chaque cancer et sert de base à la <strong>stadification</strong>, qui oriente le choix du traitement et le pronostic.</p>"},{"i":"7f267c4c29d4","n":292,"o":"292-15","u":"Suivi et/ou pronostic","t":"Connaître les caractéristiques pronostiques cliniques","q":"Quels sont les deux facteurs pronostiques cliniques les plus discriminants en oncologie, et pourquoi sont-ils importants ?","a":"<p>Les deux facteurs pronostiques cliniques les plus discriminants sont le <strong>performance status (PS)</strong> et la <strong>dénutrition</strong>. Ils sont cruciaux car ils conditionnent directement la faisabilité et la tolérance des traitements envisagés pour le cancer.</p>"},{"i":"93a70593d940","n":292,"o":"292-15","u":"Suivi et/ou pronostic","t":"Connaître les caractéristiques pronostiques cliniques","q":"Quels sont les facteurs pronostiques cliniques liés au patient dans l'évaluation d'un cancer, au-delà du stade TNM ?","a":"<p>Les facteurs pronostiques cliniques propres au patient incluent :</p><ul><li>Le <strong>performance status</strong> (PS)</li><li>La <strong>dénutrition</strong></li><li>Les <strong>comorbidités</strong>, en particulier les dysfonctions d'organe préexistantes.</li></ul>"},{"i":"a1fda962a025","n":292,"o":"292-15","u":"Suivi et/ou pronostic","t":"Connaître les caractéristiques pronostiques cliniques","q":"Quels sont les facteurs pronostiques cliniques liés au retentissement du cancer lui-même ?","a":"<p>Les facteurs pronostiques cliniques liés au retentissement du cancer sont :</p><ul><li>Les <strong>métastases osseuses avec complications neurologiques</strong>.</li><li>Les <strong>métastases à risque de saignement</strong>.</li><li>La <strong>dysfonction d'organe par envahissement tumoral</strong>.</li></ul>"},{"i":"11ceab653826","n":292,"o":"292-2","u":"Définition","t":"Connaître la définition des syndromes tumoraux","q":"Quelle est la définition du syndrome paranéoplasique en cancérologie et ses caractéristiques ?","a":"<p>Le syndrome paranéoplasique désigne des signes cliniques liés à une <strong>tumeur fonctionnelle sécrétante</strong> (hormones, cytokines) ou à une <strong>maladie auto-immune associée au cancer</strong>. Ces manifestations sont observées à <strong>distance de la tumeur</strong>, <strong>sans lien direct avec des métastases</strong>. Il peut être <strong>inaugural</strong>, précéder la détection du cancer et régresse généralement avec le traitement de la tumeur.</p>"},{"i":"20afb3a38970","n":292,"o":"292-2","u":"Définition","t":"Connaître la définition des syndromes tumoraux","q":"Quelle est la définition du syndrome tumoral en cancérologie ?","a":"<p>Le syndrome tumoral regroupe l'ensemble des signes cliniques liés à la présence d'une <strong>masse tumorale</strong> et à ses conséquences <strong>loco-régionales</strong>, telles que la <strong>compression</strong> d'organes avoisinants, l'<strong>envahissement</strong> tissulaire ou l'<strong>obstruction</strong> de conduits naturels.</p>"},{"i":"3126955772fa","n":292,"o":"292-2","u":"Définition","t":"Connaître la définition des syndromes tumoraux","q":"Quelle est la définition du syndrome cachectique et inflammatoire en cancérologie ?","a":"<p>Le syndrome cachectique et inflammatoire correspond à l'ensemble des signes liés à l'<strong>altération de l'état général</strong> et à l'<strong>état inflammatoire</strong> induits par le cancer. Il se manifeste par une <strong>asthénie</strong>, une <strong>anorexie</strong>, un <strong>amaigrissement</strong> et une <strong>fièvre</strong>.</p>"},{"i":"380f7fbde6ad","n":292,"o":"292-3","u":"Diagnostic positif","t":"Connaître la démarche diagnostique des cancers","q":"Comment l'imagerie est-elle orientée dans la démarche diagnostique d'un cancer en fonction de la présentation clinique (syndrome de masse, cachexie/fièvre isolée, syndrome paranéoplasique) ?","a":"<p>L'orientation de l'imagerie dépend de la présentation :</p><ul><li>En cas de <strong>syndrome de masse</strong> (signe d'organe) : l'examen est <strong>guidé par la clinique</strong> (ex : mammographie pour le sein, TDM thoracique pour le respiratoire, endoscopie digestive/ORL, cystoscopie).</li><li>En cas de <strong>cachexie ou fièvre isolée</strong> : une <strong>imagerie non orientée</strong> est réalisée, typiquement un <strong>TDM thoraco-abdomino-pelvien (TAP)</strong>, suivi d'un TEP-TDM en 2<sup>ème</sup> intention si besoin.</li><li>En cas de <strong>syndrome paranéoplasique</strong> : une <strong>imagerie large</strong> et de la <strong>médecine nucléaire</strong> (scintigraphie, TEP-TDM) sont privilégiées, ciblant en priorité le poumon et le sein.</li></ul>"},{"i":"69bd0d9039e6","n":292,"o":"292-3","u":"Diagnostic positif","t":"Connaître la démarche diagnostique des cancers","q":"Quelle est la règle d'or concernant la preuve diagnostique avant l'instauration d'un traitement spécifique du cancer ?","a":"<p>La règle d'or est qu'<strong>aucun traitement spécifique</strong> du cancer ne doit être débuté <strong>sans preuve anatomopathologique</strong> (histologique ou cytologique). L'imagerie seule ne suffit jamais pour affirmer le diagnostic.</p>"},{"i":"e2d4e80b2f4e","n":292,"o":"292-3","u":"Diagnostic positif","t":"Connaître la démarche diagnostique des cancers","q":"Quelle est la séquence ordonnée de la démarche diagnostique des cancers, de la suspicion à la stadification ?","a":"<p>La démarche diagnostique des cancers suit une séquence ordonnée :</p><ul><li><strong>Suspicion clinique</strong>.</li><li><strong>Imagerie évocatrice</strong>.</li><li><strong>Preuve anatomopathologique obligatoire</strong>.</li><li><strong>Bilan d'extension et pré-thérapeutique</strong>.</li><li><strong>Stadification TNM</strong>.</li></ul>"},{"i":"f9daac4e8ae3","n":292,"o":"292-3","u":"Diagnostic positif","t":"Connaître la démarche diagnostique des cancers","q":"Dans la démarche diagnostique des cancers, quels sont les différents modes de révélation pouvant conduire à une suspicion ?","a":"<p>La suspicion de cancer peut survenir par :</p><ul><li>Des <strong>signes d'appel</strong> (généraux ou d'organe).</li><li>Une <strong>découverte fortuite</strong>.</li><li>Dans le cadre d'un <strong>dépistage</strong>.</li></ul>"},{"i":"2679bd66f6ff","n":292,"o":"292-4","u":"Diagnostic positif","t":"Connaître les principaux syndromes paranéoplasiques","q":"Quels syndromes paranéoplasiques neurologiques doivent être connus et à quels cancers sont-ils associés ?","a":"<ul><li>L'<strong>ataxie cérébelleuse paranéoplasique</strong> est liée à la présence d'anticorps <strong>anti-Hu</strong> ou <strong>anti-Yo</strong> et est associée au <strong>cancer bronchique à petites cellules (CPC)</strong>, au sein et à l'ovaire.</li><li>Le <strong>syndrome de Lambert-Eaton</strong>, causé par des anticorps <strong>anti-canaux calciques</strong>, est principalement observé dans le <strong>CPC</strong>.</li><li>L'<strong>encéphalite limbique</strong>, associée aux anticorps <strong>anti-NMDA</strong> ou <strong>anti-Hu</strong>, est également souvent liée au <strong>CPC</strong>.</li></ul>"},{"i":"bcaa762e7192","n":292,"o":"292-4","u":"Diagnostic positif","t":"Connaître les principaux syndromes paranéoplasiques","q":"Quels sont les syndromes paranéoplasiques endocriniens majeurs et leurs cancers associés ?","a":"<ul><li>Le <strong>syndrome de Schwartz-Bartter (SIADH)</strong>, dû à la production d'<strong>ADH ectopique</strong>, est observé le plus souvent dans le <strong>cancer bronchique à petites cellules (CPC)</strong>, mais aussi dans des atteintes du SNC ou de la prostate.</li><li>Le <strong>syndrome de Cushing</strong>, par production d'<strong>ACTH ectopique</strong>, est également principalement associé au <strong>CPC</strong>.</li><li>L'<strong>hypercalcémie</strong>, souvent liée à la production de <strong>PTH-rp</strong>, se retrouve dans le <strong>cancer bronchique non à petites cellules (CNPC)</strong>, les cancers du sein, du rein, de l'ovaire, et le myélome.</li><li>Le <strong>syndrome carcinoïde</strong>, par production de <strong>sérotonine</strong> (avec augmentation de <strong>5-HIAA</strong>), est caractéristique des <strong>tumeurs neuroendocrines (TNE) du grêle</strong>.</li></ul>"},{"i":"c69b03108a0f","n":292,"o":"292-4","u":"Diagnostic positif","t":"Connaître les principaux syndromes paranéoplasiques","q":"Quel est le syndrome paranéoplasique hématologique le plus fréquent et à quels cancers est-il particulièrement associé ?","a":"<p>Le syndrome paranéoplasique hématologique le plus fréquent est la <strong>maladie thromboembolique veineuse (MTEV)</strong>, incluant le <strong>syndrome de Trousseau</strong> et la <strong>CIVD</strong>, par un état d'hypercoagulabilité. Il peut survenir dans tout cancer, mais est particulièrement associé aux cancers du <strong>pancréas</strong>, de l'<strong>estomac</strong> et du <strong>poumon</strong>.</p>"},{"i":"dd9706bd2372","n":292,"o":"292-4","u":"Diagnostic positif","t":"Connaître les principaux syndromes paranéoplasiques","q":"Qu'est-ce qu'un syndrome paranéoplasique ?","a":"<p>Les syndromes paranéoplasiques sont des manifestations systémiques associées à un cancer, mais <strong>non liées directement aux métastases</strong>. Ils résultent soit d'une <strong>production tumorale de substances pseudo-hormonales</strong>, soit d'un <strong>mécanisme auto-immun</strong>. Le <strong>poumon</strong> (notamment le cancer bronchique à petites cellules et non à petites cellules) est le cancer le plus fréquemment à l'origine de ces syndromes.</p>"},{"i":"f6e7909deb02","n":292,"o":"292-4","u":"Diagnostic positif","t":"Connaître les principaux syndromes paranéoplasiques","q":"Citez deux syndromes paranéoplasiques cutanés ou auto-immuns et leurs cancers d'association.","a":"<ul><li>La <strong>dermatomyosite / polymyosite</strong>, en tant que manifestation auto-immune, est associée au <strong>cancer bronchique non à petites cellules (CNPC)</strong> ainsi qu'aux cancers du sein et de l'ovaire.</li><li>L'<strong>ostéoarthropathie hypertrophiante pneumique (syndrome de Pierre-Marie)</strong> est également de mécanisme auto-immun et fortement associée au <strong>CNPC</strong>.</li></ul>"},{"i":"afea7d3a8033","n":292,"o":"292-6","u":"Diagnostic positif","t":"Connaître les signes généraux en cancérologie","q":"Quels sont les autres signes généraux importants à rechercher en cancérologie, en dehors de l'AEG ?","a":"<p>En dehors de l'altération de l'état général (AEG), il faut rechercher :</p><ul><li>La <strong>fièvre</strong> inexpliquée.</li><li>Les <strong>sueurs nocturnes</strong>.</li></ul><p>Ces deux derniers signes sont notamment connus comme faisant partie des <strong>signes B des lymphomes</strong>.</p>"},{"i":"df7c907b685b","n":292,"o":"292-6","u":"Diagnostic positif","t":"Connaître les signes généraux en cancérologie","q":"Comment doit-on quantifier l'amaigrissement en cancérologie et quel seuil est significatif de dénutrition ?","a":"<p>L'amaigrissement doit être quantifié en précisant :</p><ul><li>Le <strong>poids actuel</strong> du patient.</li><li>Le <strong>pourcentage de perte de poids</strong> par rapport au poids de base.</li><li>Le <strong>délai d'installation</strong> de cette perte de poids.</li></ul><p>Une perte de poids de <strong>≥ 5 % en 1 mois</strong> ou <strong>≥ 10 % en 6 mois</strong> est considérée comme significative d'une <strong>dénutrition</strong>. C'est un facteur pronostique important et un critère décisionnel thérapeutique.</p>"},{"i":"e821b41ef6ea","n":292,"o":"292-6","u":"Diagnostic positif","t":"Connaître les signes généraux en cancérologie","q":"Qu'est-ce que l'altération de l'état général (AEG) en cancérologie et de quelle triade est-elle composée ?","a":"<p>L'altération de l'état général (AEG) en cancérologie est un ensemble de signes généraux non spécifiques mais évocateurs, traduisant un syndrome cachectique et inflammatoire. Elle est composée de la triade :</p><ul><li><strong>Asthénie</strong></li><li><strong>Anorexie</strong></li><li><strong>Amaigrissement</strong></li></ul><p>Elle peut évoluer vers la <strong>dénutrition</strong> et la <strong>sarcopénie</strong>.</p>"},{"i":"4059d5306457","n":292,"o":"292-7","u":"Examens complémentaires","t":"Connaître la biologie et principales altérations biologiques","q":"Quels sont les principaux syndromes paranéoplasiques révélés par des anomalies biologiques spécifiques ?","a":"<p>Les syndromes paranéoplasiques peuvent se manifester par :</p><ul><li>Une <strong>hypercalcémie</strong> due à la sécrétion de <strong>PTH-rp</strong> (peptide apparenté à la parathormone).</li><li>Une <strong>hyponatrémie</strong> secondaire à un <strong>SIADH</strong> (syndrome de sécrétion inappropriée d'hormone antidiurétique).</li><li>Des <strong>dosages hormonaux anormaux</strong>.</li><li>La présence d'<strong>auto-anticorps</strong>.</li></ul>"},{"i":"6889fcc98941","n":292,"o":"292-7","u":"Examens complémentaires","t":"Connaître la biologie et principales altérations biologiques","q":"Quels sont les principaux signes d'appel biochimiques pouvant orienter vers le diagnostic de cancer ?","a":"<p>Les anomalies biochimiques pouvant orienter vers un cancer incluent :</p><ul><li>Une <strong>hyponatrémie</strong> et une <strong>hypercalcémie</strong> à l'ionogramme.</li><li>Une <strong>élévation de la créatininémie</strong>, pouvant signaler un obstacle urinaire.</li><li>Une <strong>cholestase</strong> ou une <strong>cytolyse hépatique</strong>, indiquant une atteinte du foie.</li><li>Une <strong>élévation des LDH</strong>, marqueur de prolifération cellulaire, notamment dans les lymphomes.</li><li>La présence de <strong>sang dans les selles</strong> détectée par un test immunologique (dépistage du cancer colorectal).</li></ul>"},{"i":"8770a0f4a10d","n":292,"o":"292-7","u":"Examens complémentaires","t":"Connaître la biologie et principales altérations biologiques","q":"Quelles sont les anomalies biologiques pouvant évoquer un cancer dans un contexte de cachexie/inflammation ?","a":"<p>Dans le contexte d'une cachexie/inflammation liée à un cancer, on peut retrouver :</p><ul><li>Une <strong>baisse de l'albumine</strong> et de la <strong>préalbumine</strong>.</li><li>Une <strong>élévation de la CRP</strong> et du <strong>fibrinogène</strong>.</li></ul>"},{"i":"dd9cd9045c16","n":292,"o":"292-7","u":"Examens complémentaires","t":"Connaître la biologie et principales altérations biologiques","q":"Quels sont les principaux signes d'appel hématologiques (<abbr title=\"Numération Formule Sanguine\">NFS</abbr>) pouvant faire évoquer un cancer ?","a":"<p>La <abbr title=\"Numération Formule Sanguine\">NFS</abbr> peut révéler des signes d'appel hématologiques comme :</p><ul><li>Une <strong>anémie microcytaire ferriprive</strong>, suggérant un saignement chronique (ex: digestif).</li><li>Une <strong>pancytopénie d'origine centrale</strong>, pouvant indiquer un envahissement médullaire (avec myélémie ou blastes au frottis).</li><li>Une <strong>thrombocytose</strong> ou une <strong>hyperleucocytose</strong>, souvent dans un contexte d'inflammation chronique.</li><li>Une <strong>anémie hémolytique mécanique</strong> associée à une <strong>thrombopénie</strong>, évocatrice d'une microangiopathie thrombotique.</li></ul>"},{"i":"fb9a41e9380e","n":292,"o":"292-7","u":"Examens complémentaires","t":"Connaître la biologie et principales altérations biologiques","q":"Quelles sont les anomalies biologiques associées à un syndrome de masse cancéreux (hors syndromes paranéoplasiques ou hématologiques) ?","a":"<p>Un syndrome de masse cancéreux peut entraîner :</p><ul><li>Des <strong>perturbations des fonctions d'organe</strong> (ex: élévation de la créatininémie en cas d'obstacle, cholestase/cytolyse hépatique).</li><li>Une <strong>élévation des LDH</strong> (marqueur de prolifération cellulaire).</li><li>Une <strong>hypercalcémie</strong>, notamment en cas de métastases osseuses.</li><li>Un possible <strong>syndrome de lyse spontané</strong> dans le cas de tumeurs à croissance rapide.</li></ul>"},{"i":"8234354c0e92","n":292,"o":"292-8","u":"Définition","t":"Connaître les principes d’utilisation des marqueurs tumoraux","q":"Quels sont les pièges classiques et la règle d'interprétation des marqueurs tumoraux à connaître pour l'EDN ?","a":"<p>Un marqueur tumoral peut être <strong>élevé dans des affections non cancéreuses</strong> et, à l'inverse, être <strong>normal en présence d'un cancer</strong>. Il ne permet <strong>jamais de poser un diagnostic</strong> à lui seul et doit toujours être interprété en association avec l'<strong>imagerie</strong> et l'<strong>histologie</strong>.</p>"},{"i":"b932d4a84b8c","n":292,"o":"292-8","u":"Définition","t":"Connaître les principes d’utilisation des marqueurs tumoraux","q":"Quelle est la définition d'un marqueur tumoral selon l'EDN et quelle est sa principale indication ?","a":"<p>Un marqueur tumoral est une <strong>substance</strong> (retrouvée dans le sang, les urines, ou les tissus) dont la présence ou l'élévation peut indiquer un cancer. La principale indication des marqueurs tumoraux est la <strong>surveillance</strong>.</p>"},{"i":"e90c74d27718","n":292,"o":"292-8","u":"Définition","t":"Connaître les principes d’utilisation des marqueurs tumoraux","q":"Dans quelles situations les marqueurs tumoraux sont-ils utilisés en dépistage ou diagnostic selon les recommandations de l'EDN ?","a":"<ul><li><strong>Dépistage</strong> : Très limité, seuls le <strong>PSA</strong> (cancer de la prostate) et l'<strong>αFP</strong> (carcinome hépatocellulaire chez le cirrhotique) sont utilisés en dépistage ciblé.</li><li><strong>Diagnostic</strong> : Quasi aucun, sauf pour les <strong>tumeurs germinales</strong> (avec l'<strong>hCG</strong>, l'<strong>αFP</strong>, la <strong>LDH</strong>).</li></ul>"},{"i":"118cf87eabea","n":292,"o":"292-9","u":"Diagnostic positif","t":"Connaître la place de l’examen anatomo-pathologique en cancérologie","q":"Quels sont les objectifs de l'examen anatomopathologique en cancérologie ?","a":"<ul><li><strong>Diagnostic</strong> : il affirme la malignité, précise le type histologique et l'organe d'origine (avec l'immunohistochimie si besoin).</li><li><strong>Pronostic</strong> : il évalue l'activité mitotique, le degré d'invasion (emboles, engainements), le degré de différenciation et les grades (Gleason, Ki67, Elston-Ellis).</li><li><strong>Thérapeutique</strong> : il recherche des anomalies moléculaires pour les thérapies ciblées (ex: EGFR poumon, RH/HER2 sein, RAS côlon).</li></ul>"},{"i":"6553b4665bb1","n":292,"o":"292-9","u":"Diagnostic positif","t":"Connaître la place de l’examen anatomo-pathologique en cancérologie","q":"Quelles sont les caractéristiques de la cytologie comme technique d'examen anatomopathologique en cancérologie ?","a":"<p>La cytologie étudie des <strong>cellules isolées</strong> (frottis, ponction à l'aiguille fine, liquide). Elle n'a de valeur que si elle est <strong>positive</strong> (mauvaise valeur prédictive négative). Elle ne permet pas de préciser le type histologique ni la différenciation.</p>"},{"i":"67c15fdfff84","n":292,"o":"292-9","u":"Diagnostic positif","t":"Connaître la place de l’examen anatomo-pathologique en cancérologie","q":"Quel est le principe fondamental du diagnostic de cancer ?","a":"<p>Le diagnostic de cancer est posé par l'examen <strong>histologique ou cytologique</strong> d'un échantillon de tissu tumoral (tumeur primitive ou métastase). Il n'y a pas de diagnostic de cancer sans <strong>preuve anatomopathologique</strong>.</p>"},{"i":"6c54b0903361","n":292,"o":"292-9","u":"Diagnostic positif","t":"Connaître la place de l’examen anatomo-pathologique en cancérologie","q":"Dans quels cas l'immunohistochimie est-elle obligatoire en anatomopathologie cancérologique ?","a":"<p>L'immunohistochimie est obligatoire pour le <strong>mésothéliome</strong>, les <strong>TNE du pancréas</strong>, le <strong>lymphome</strong>, les <strong>GIST</strong> et les <strong>CPC</strong>.</p>"},{"i":"a7413974d7e7","n":292,"o":"292-9","u":"Diagnostic positif","t":"Connaître la place de l’examen anatomo-pathologique en cancérologie","q":"Quels sont les principes de choix du prélèvement pour un examen anatomopathologique en cancérologie ?","a":"<ul><li>Privilégier les sites <strong>accessibles</strong> (ex: lésion mammaire, hépatique, ganglionnaire sus-claviculaire).</li><li>Privilégier la <strong>biopsie à la cytoponction</strong> afin d'obtenir plus de tissu et de permettre des analyses moléculaires.</li><li>La biopsie osseuse a une rentabilité modérée (décalcification, analyses moléculaires difficiles).</li></ul>"},{"i":"c1458786c7da","n":292,"o":"292-9","u":"Diagnostic positif","t":"Connaître la place de l’examen anatomo-pathologique en cancérologie","q":"Quelles sont les pathologies nécessitant une double lecture systématique par l'INCa en anatomopathologie cancérologique ?","a":"<p>Une double lecture systématique par l'INCa est requise pour les <strong>sarcomes</strong>, les <strong>lymphomes</strong>, les <strong>mésothéliomes</strong> et les <strong>TNE rares</strong>.</p>"},{"i":"d80010b2aa17","n":292,"o":"292-9","u":"Diagnostic positif","t":"Connaître la place de l’examen anatomo-pathologique en cancérologie","q":"Quelles sont les caractéristiques de l'histologie comme technique d'examen anatomopathologique en cancérologie ?","a":"<p>L'histologie est réalisée sur une <strong>biopsie ou une pièce opératoire</strong>. Elle étudie les <strong>anomalies cytologiques et architecturales</strong> (type, invasion, différenciation). Sa valeur prédictive négative est supérieure à celle de la cytologie.</p>"}]};